// Agent player (issues #75, #68): the tools an AI agent uses to play one hero. Pure data, shared by
// the MCP server (scripts/relay-mcp.mjs), the headless host and the docs. Each tool:
//   {name, desc, act, args:{argName:{type:'string'|'integer'|'number'|'array' (of strings), desc, optional?, enum?}}}
// act: true for tools that change the world (rate limited per game hour), false for reads.
// The game side is src/sim/player.js; every call only ever touches the agent's own hero.
// In-game only (issue #123): a hero's tools answer with what its character perceives (sight, earshot,
// the party channel, its own sheet, journal and memories) and never with DM notes, the DM log or
// another hero's journal, memories, mind or prompt (scripts/channelcheck.mjs proves it).
export const PLAYER_TOOLS=[
  {name:'look',act:false,desc:'Look around: the place, time, weather, and the heroes, townsfolk and monsters you can see (about 12 tiles, less in fog or storms; the whole town square when in town). A creature you do not know is described, not named, with your own read of its threat ("hard to judge" until you learn it). Also returns what happened since your last call.',args:{}},
  {name:'status',act:false,desc:'Your hero: level, HP, XP, gold, what you are doing, your command queue, quest, oath, origin, traits, party, adventure and any scene choice waiting for you, plus the places you know and can travel to.',args:{}},
  {name:'inventory',act:false,desc:'Your seven equipment slots and your pack, by index: trade goods to sell, spare gear to equip, consumables (potions, bandages, rations, torches, antidotes, scrolls) to use, and quest items. Shows how many slots are used.',args:{}},
  {name:'use_item',act:true,desc:'Use a consumable from your pack (by pack index). A potion heals in a fight (one every few seconds); a bandage or ration only out of one; a torch is lit at camp; an antidote cures venom; a scroll recalls you home or wards you for a short time. target_id (or target by name): a party member within 4 tiles to tend instead of yourself.',args:{index:{type:'integer',desc:'Pack index from inventory'},target_id:{type:'integer',desc:'Party member to tend (default you)',optional:true},target:{type:'string',desc:'Or the party member\'s name',optional:true}}},
  {name:'use_ability',act:true,desc:'Use one of your class abilities (listed with cooldowns in status.abilities): a strike, ward, heal, snare, taunt or step. An attack ability takes the place of a weapon blow. target_id or target (a name): the foe (default the one you are fighting) for foe abilities, or a party member within range for a ward; self and area abilities need none. Abilities are yours alone; each has a cooldown in seconds.',args:{ability:{type:'string',desc:'Ability name or id from status.abilities, e.g. "Challenge" or "deadeye"'},target_id:{type:'integer',desc:'Foe id from look, or a party member id',optional:true},target:{type:'string',desc:'Or a name: a companion, or a foe as you know it',optional:true}}},
  {name:'stabilize',act:true,desc:'Stop the bleeding of a downed hero of your side in sight (a companion at zero health, rolling death saves): you go to their side and bind them with a Linen Bandage (sure) or roll d20 + your Healing against 10 every 10 game minutes. Stable, they stop rolling saves and wake on 1 HP in about an hour, or at once when healed. who: their name (or hero_id); with one downed in sight it may be left out.',args:{who:{type:'string',desc:'The downed hero\'s name',optional:true},hero_id:{type:'integer',desc:'Or their hero id from look',optional:true}}},
  {name:'tend',act:true,desc:'Tend a downed hero of your side in sight with everything you have: your class heal from 5 tiles (it brings them up 15% of their health higher), a healing potion at their side if they ride in your party, then a Linen Bandage or a stabilize roll. who: their name (or hero_id).',args:{who:{type:'string',desc:'The downed hero\'s name',optional:true},hero_id:{type:'integer',desc:'Or their hero id from look',optional:true}}},
  {name:'carry',act:true,desc:'Carry a downed hero of your side in sight to safety: to your town (default), the company camp or your leader, at 60% of your pace, and lay them down to wake. One still bleeding is stabilized first. who: their name (or hero_id).',args:{who:{type:'string',desc:'The downed hero\'s name',optional:true},hero_id:{type:'integer',desc:'Or their hero id from look',optional:true},to:{type:'string',enum:['town','camp','leader'],desc:'Where to carry them (default town)',optional:true}}},
  {name:'combat_log',act:false,desc:'Your own recent fights and what happened in them: damage you dealt and took, healing, abilities and items you used, crits, kills and how each fight ended (won, fled, died, ongoing). Only your hero. n: how many fights (1-10, default 3).',args:{n:{type:'integer',desc:'How many recent fights (1-10)',optional:true}}},
  {name:'choose_specialisation',act:true,desc:'At level 10 take one of the two paths of your class (status.specialisation lists them): it adds score points, trains a skill, and brings a passive and one more ability. Permanent; until you choose, you have neither. Pass the path name or id.',args:{path:{type:'string',desc:'Path name or id from status.specialisation, e.g. "Mender" or "battlecleric"'}}},
  {name:'drop',act:true,desc:'Throw an item or some of a stack out of your pack (gone for good). Quest items cannot be dropped.',args:{index:{type:'integer',desc:'Pack index from inventory'},count:{type:'integer',desc:'Units to drop (default the whole stack)',optional:true}}},
  {name:'give',act:true,desc:'Give an item, or some of a stack, to a member of your party within 4 tiles. Name the item (item: "Redroot Draught", "potion", "2 rations", part of a name; any case) or give its pack index from inventory: one of the two is needed. A name that fits several things lists them with their indexes. Gear must be made for their class. Quest items are bound to their bearer.',args:{item:{type:'string',desc:'The item by name, e.g. "Redroot Draught" or "2 rations" (or use index)',optional:true},index:{type:'integer',desc:'Or its pack index from inventory',optional:true},hero_id:{type:'integer',desc:'The party member\'s hero id from look',optional:true},to:{type:'string',desc:'Or the party member\'s name',optional:true},count:{type:'integer',desc:'Units to give (default 1)',optional:true}}},
  {name:'move_to',act:true,desc:'Walk somewhere. Target: a town spot (auction house, quest giver, gate, inn, smith, chapel, square, graveyard), a townsperson by name or role, "home", a region or place you know (status.places: where you have been or been told of), a friendly town, a companion in sight, a label the game gave you ("gate in Highgate", "the inn"), a direction to explore ("north", "explore southeast", "east 25"), or map coordinates "x,y". Places you have never heard of are refused. Replaces your current command.',args:{target:{type:'string',desc:'Where to go'},force:{type:'string',desc:'"yes" to walk on into a region far above you without stopping at its edge (otherwise the first such walk stops there with a warning; the same call again goes on)',optional:true}}},
  {name:'talk',act:true,desc:'Speak to a townsperson or a person met on the road (by name or role, within 4 tiles) or to a hero of your own faction nearby (by name or id). With the Fellowship, text is what you say: it opens a short conversation; the person answers in their own words (at once, or as a line you hear soon after) and may offer trade, a rumour, a job, a blessing, or turn away or hostile. Your next say near them goes on with it.',args:{target:{type:'string',desc:'Name, role or hero id'},text:{type:'string',desc:'What you say to them (optional; up to 200 characters)',optional:true}}},
  {name:'say',act:true,desc:'Say a line out loud (up to 200 characters; longer is refused). Do not start with your own name: the game shows who speaks. Heroes within earshot hear it; it shows as a speech bubble.',args:{text:{type:'string',desc:'What you say'}}},
  {name:'join_party',act:true,desc:'Ask to ride with a hero of your faction within 6 tiles. Toward a hero who chooses their own road (or a companion of a company) it asks that company’s leader, face to face and aloud: they answer with accept or decline within an hour. Toward any other hero it works at once: you join (or form a party with) them if within 3 levels; loners refuse; a party of 3 is full. With a companion of your own company it is a promise to fall in with them again.',args:{hero_id:{type:'integer',desc:'The other hero\'s id from look',optional:true},who:{type:'string',desc:'Or the hero\'s name',optional:true}}},
  {name:'invite',act:true,desc:'Offer a hero of your faction within 6 tiles a place in your company, said aloud (everyone in earshot hears it; text is your words, else "Ride with me?"). Alone, an accepted invite forms a company of two. A hero who chooses their own road answers in their own time (accept or decline, within an hour). Anyone else answers at once by their nature: loners refuse, so do heroes more than 3 levels from you, already in a party or on a job of their own, or holding a grudge against one of yours; one who agrees rides with you as a companion (follows your leader, fights, heals and flees by instinct, never leads). A company holds at most 8 heroes, at most 5 of them choosing their own road. Refused for a hero who leads a company of their own or rides with one, in a fight, a duel, a dungeon, a raid or at camp.',args:{hero_id:{type:'integer',desc:'The hero’s id from look',optional:true},name:{type:'string',desc:'Or the hero’s name',optional:true},text:{type:'string',desc:'What you say when you ask (up to 200 characters)',optional:true}}},
  {name:'accept',act:true,desc:'Accept an offer to ride together (its id is in the event and your state header): an invite puts you in that company; an ask (someone’s join_party) lets them into yours. They must still be within 6 tiles. Refused while you ride with a company of 2 or more of your own (you would have to leave it first), during a scene at the table, or when the company is full.',args:{offer_id:{type:'integer',desc:'The offer id'}}},
  {name:'decline',act:true,desc:'Turn down an offer to ride together. text: what you say (aloud, they hear it); without it you shake your head. Unanswered offers lapse after an hour.',args:{offer_id:{type:'integer',desc:'The offer id'},text:{type:'string',desc:'Your answer, in your own words',optional:true}}},
  {name:'leave_party',act:true,desc:'Leave your party. In the Fellowship, split off with a plan: say where and when you will meet again (where, when_hours). Beyond shouting range (about 12 tiles) you cannot talk to your companions, and the plan is recorded only for those who hear it now.',args:{where:{type:'string',desc:'Fellowship: where to meet again (a place or town)',optional:true},when_hours:{type:'integer',desc:'Fellowship: hours from now to meet (1-48)',optional:true},for_good:{type:'boolean',desc:'yes: leave your company for good and ride alone as a company of one (bonds suffer; refused if you already ride alone, in a fight, at a scene, in a dungeon or at camp)',optional:true}}},
  {name:'companions',act:false,desc:'Your company as you know it: who rides with you (name, class, level), whether each is beside you or last seen near which place and how long ago (never exact positions), open meeting plans, couriers you have out, offers open to you and from you, and who a say or a party shout reaches now (earshot). Read-only.',args:{}},
  {name:'follow',act:true,desc:'Walk at the side of a hero you can see without joining them (no shared XP, no votes, no party shouts): you keep their pace until you give another order (move_to, hunt, fight or rest end it) or the hours run out. You still defend yourself when struck. If you lose sight of them you walk to where you last saw them; if they are not there either you stop and are told. Not an enemy out in the open; a company leader uses lead_to instead.',args:{hero_id:{type:'integer',desc:'The hero to follow (id from look)',optional:true},name:{type:'string',desc:'Or their name, as look shows it',optional:true},hours:{type:'integer',desc:'How long to follow (1-12 game hours; default until another order)',optional:true}}},
  {name:'list_jobs',act:false,desc:'In your home town: the adventures posted at the gate (and your own adventure if you have one to resume), in the words of the job, how many blades it wants, and what the gate says about it. The job-giver decides at take_adventure whether you will do.',args:{}},
  {name:'take_adventure',act:true,desc:'In the Fellowship the party decides: a member proposes the job (propose kind job) and the leader settles it. In your home town: take a posted job (or resume your own adventure) by its id. The adventure then leads you scene by scene; choice scenes wait for choose().',args:{job_id:{type:'integer',desc:'Job id from list_jobs'}}},
  {name:'choose',act:true,desc:'Pick a branch at your adventure\'s current choice scene: "a" (the bold road) or "b" (the careful one). Unanswered choices fall to your instincts after a while.',args:{option:{type:'string',enum:['a','b'],desc:'a or b'}}},
  {name:'fight',act:true,desc:'Attack a monster (or an enemy-faction hero outside Thornvale) you can see, by id from look (or target: its name as you know it, the nearest one). Fighting a creature teaches you its name and its measure. You break off and run home below flee_below percent HP (default 15).',args:{target_id:{type:'integer',desc:'Monster or hero id',optional:true},target:{type:'string',desc:'Or its name, e.g. "Timber Wolf"',optional:true},flee_below:{type:'integer',desc:'Flee below this % HP (5-60)',optional:true}}},
  {name:'hunt',act:true,desc:'Hunt where you stand until you have killed count, or your HP drops below 45%. prey: a creature you know by name (only those); without it you take on whatever is around, except what you have learned to fear. Nobody picks safe prey for you: choose well. where: a region or place you know (or a direction, or "x,y"): you walk there first, then hunt (from town too).',args:{where:{type:'string',desc:'Where to hunt: a region or place you know, e.g. "Lowmark", a direction ("north") or "x,y"; leave out to hunt where you stand',optional:true},count:{type:'integer',desc:'Kills to make (1-10, default 3)',optional:true},prey:{type:'string',desc:'A creature you know by name, e.g. "Timber Wolf" (see lore)',optional:true},flee_below:{type:'integer',desc:'Flee a fight below this % HP (5-60)',optional:true},force:{type:'string',desc:'"yes" to walk on into a region far above you without stopping at its edge',optional:true}}},
  {name:'pay',act:true,desc:'Pay gold to a hero (any faction) or a townsperson within 4 tiles: a share for a companion, a tip, a bribe, a debt. The gold moves at once; both of you record it and those near hear it. A person you pay warms to you a step for every 10 gold (twice a game day at most). Refused: more than you hold, zero, in a fight.',args:{to:{type:'string',desc:'The name or id of a hero, or a townsperson by name or role, within 4 tiles',optional:true},gold:{type:'integer',desc:'Whole gold, above zero',optional:true},why:{type:'string',desc:'A few words, e.g. "for the potions"',optional:true}}},
  {name:'hire',act:true,desc:'Hire a sellsword, a drover or a guide (or anyone placed on the road who wants coin) within 4 tiles to ride with your company for gold a day: 4 gold plus your level a day, paid up front for 1 to 5 days. They ride as a scripted companion at the lowest level of your company, with their own name: they follow the leader, fight, heal or scout by what they are, flee by instinct, never lead and never vote. A guide knows the roads of their region: places lists its landmarks as heard of and a walk into danger carries their warning. When the days are up, or on dismiss, they walk home; one that falls is dead for good. Refused: a company of 8, a fight or a scene, gold short, a person who dislikes you, a town whose sellswords are wary after a wipe.',args:{npc:{type:'string',desc:'The name or role of the person within 4 tiles ("sellsword", a name)',optional:true},days:{type:'integer',desc:'Paid days, 1 to 5 (default 1)',optional:true}}},
  {name:'dismiss',act:true,desc:'Pay off a hire: they keep the wage (no refund for unused days) and walk home. npc is the name of the hire; with one hire riding, it may be left out. Refused while the hire is in a fight.',args:{npc:{type:'string',desc:'Name of the hire',optional:true}}},
  {name:'challenge',act:true,desc:'Challenge a hero of your own faction within 6 tiles (a companion or not) to an honour duel, said aloud: to "first blood" (the first hit ends it) or to "yield" (until one yields at 30% health). They answer (a scripted hero at once; an agent within an hour) and a duel is played at the table, the two of you in turns: strike, an ability, guard or yield. No one dies or goes down; HP lost is real. The winner gains honour; both remember it; a leader beaten by a companion yields the lead. In Thornvale only first blood. Refused: another faction, a fight, the Crypt, a raid, a scene, camp, a hero below half health, more than 2 a game day, the same pair within 12 game hours.',args:{hero:{type:'string',desc:'The name or id of a hero of your faction within 6 tiles'},to:{type:'string',desc:'"first blood" (default) or "yield"',optional:true,enum:['first blood','yield']},text:{type:'string',desc:'What you say as you challenge them (said aloud; a plain challenge if left out)',optional:true}}},
  {name:'answer_challenge',act:true,desc:'Answer an honour duel challenge made to you (within an hour of it): accept opens the duel at the table, decline is said aloud and heard by all near (it costs you nothing). With no answer it tells you the challenge.',args:{answer:{type:'string',desc:'"accept" or "decline"',optional:true,enum:['accept','decline']},text:{type:'string',desc:'What you say as you answer (said aloud)',optional:true}}},
  {name:'mark',act:true,desc:'Name the spot you stand on (or a marker or landmark in sight) as a place of your own: a good hunting ground, a ford, a hidden camp. places lists it as yours and move_to, hunt {where} and lead_to take its name. Say the name aloud and companions in earshot learn it. 12 marks; the oldest is forgotten for a new one.',args:{name:{type:'string',desc:'The name of the place, e.g. Ford of Reeds',optional:true},note:{type:'string',desc:'What is there, in a few words',optional:true},what:{type:'string',desc:'Or a marker or landmark in sight to mark instead of where you stand',optional:true}}},
  {name:'unmark',act:true,desc:'Forget a place you marked.',args:{name:{type:'string',desc:'The name of the mark',optional:true}}},
  {name:'places',act:false,desc:'The places you know, nearest first (12 at most): your towns, regions you have been to or heard of, landmarks you have seen, and a marked spot in sight. Each with its direction and tiles from you (or from near), rough time on foot, whether you have been there or only heard of it, what folk say of it, the creatures you know live there and the danger you learned there. Any name it gives works in move_to and hunt {where}. Only what you know; never numbers.',args:{kind:{type:'string',desc:'Only this kind: town, region, landmark, place or mark (yours and told)',optional:true},about:{type:'string',desc:'Only places matching this name or a creature you know, e.g. "Timber Wolf"',optional:true},near:{type:'string',desc:'Measure from this place you know (or "x,y") instead of where you stand',optional:true}}},
  {name:'shop',act:false,desc:'What you could buy here and now, without buying: in a friendly town the gear the smiths sell (one line per slot: the piece at your level, its price, and the armor and damage it adds or loses against what you wear) and every supply (price, level, what it does); with npc, what that person who opened their trade sells. Prices are exactly what buy charges. By default a short answer: only the gear that would be better than what you wear and the supplies you can buy at your level; all: "yes" gives every slot (what you wear there, the piece on offer) and every supply, locked ones saying "needs level N". Changes nothing.',args:{npc:{type:'string',desc:'A person who offered to trade with you (name or role); leave out for the town smiths',optional:true},all:{type:'string',enum:['yes','no'],desc:'yes for the full list (every slot and supply); leave out for the short answer',optional:true}}},
  {name:'inspect',act:false,desc:'Look closely at one person, creature or item, as your hero sees it. A hero in sight: people and class, level, side, guild, how hurt they look (in words), what they are doing, the gear they wear by name, and what they are to you (party, blood debt, spoken with). A townsperson: role, side, what they are doing, their mood if you have spoken with them, whether their trade is open to you. A creature: your own read of its threat and what you have learned of it (never numbers). An item in your pack or on you (or a supply or trade good by name): what it does, whether you can wear it, what it sells for. who takes a name, part of a name, a role, an id from look, or me. Changes nothing.',args:{who:{type:'string',desc:'A name, role or id from look ("Kerin", "innkeeper", "wolf", "#42"), an item ("Redroot Draught", "main"), or me'}}},
  {name:'search',act:true,desc:'Search where you stand, or a marked place, sign or landmark close by (name it in what; you must be within about 6 tiles). It takes about 20 game minutes and you stay put. One Lore or Perception roll: success tells you what the place holds (a secret, a sign read in full, tracks of creatures near, something hidden), failure leaves the spot searched for about 6 game hours. Companions in earshot see you search. Not in a fight. examine is the free closer look.',args:{what:{type:'string',desc:'A marked place, landmark or sign in sight ("the lantern cairn", "sign"); omit to search the ground where you stand',optional:true}}},
  {name:'examine',act:false,desc:'A closer look at one marked place, landmark, sign or a town notice board in sight: what it is, what is written or carved there, and what you found if you searched it. Changes nothing and takes no time; search is how you find hidden things. inspect covers people, creatures and items.',args:{what:{type:'string',desc:'A marked place, landmark, sign or "notice board"; omit for the nearest',optional:true}}},
  {name:'lore',act:false,desc:'What you know of the world: creatures you have seen, fought, been warned of or heard named (your read of their threat, their tricks, where they live, who fell to them) and the places you know (been there, heard of it, the danger you learned there). Only what you saw, heard or were told; never numbers.',args:{about:{type:'string',desc:'Only what concerns this creature or place',optional:true}}},
  {name:'flee',act:true,desc:'Break off the current fight or duel and run for home. A monster may land one parting blow.',args:{}},
  {name:'rest',act:true,desc:'Sit and recover HP where you stand for some game minutes (default 60). Any attack interrupts. Fellowship leader: with hours (1-8) the whole company makes camp for that long (a watch is kept, sleepers heal, and the camp breaks by itself when the time is up); status.camp shows who sleeps, who watches and how long is left.',args:{minutes:{type:'integer',desc:'Game minutes (10-240)',optional:true},hours:{type:'integer',desc:'Leader only: make camp for this many game hours (1-8)',optional:true}}},
  {name:'buy',act:true,desc:'In your home town: buy a piece of gear at your level for one slot (default: your weakest). Costs 6 gold per item level; only upgrades are sold to you. Or pass item to buy supplies instead (a potion, bandage, ration, torch, antidote, scroll or a pack for more slots; prices in the error if you name one that is not sold). With npc: buy from a person who offered to trade with you (anywhere, standing near them; their stock and prices).',args:{npc:{type:'string',desc:'A person who opened their stock to you (name)',optional:true},slot:{type:'string',enum:['head','chest','hands','feet','main','off','trinket'],desc:'Slot',optional:true},item:{type:'string',desc:'A supply to buy instead of gear, for example Redroot Draught',optional:true},count:{type:'integer',desc:'How many supplies (1-10)',optional:true}}},
  {name:'sell',act:true,desc:'In your home town: sell your trade goods and spare gear at the auction house. index sells one pack entry; without it all goods and spares go (consumables and quest items are kept). With npc: sell to a person who offered to trade with you, at their prices.',args:{index:{type:'integer',desc:'Pack index from inventory',optional:true},npc:{type:'string',desc:'A person who offered to trade (name)',optional:true}}},
  {name:'auction_browse',act:false,desc:'In town: what other heroes have listed at the auction house (id, what, how many, price each, seller, hours left; gear shows its level, slot and class, and what it would add over what you wear), your own listings, and the last trades. Changes nothing.',args:{}},
  {name:'auction_list',act:true,desc:'In town: list a pack entry for other heroes to buy, instead of selling it to the house. index is the pack entry (trade goods or gear; consumables and quest items cannot be listed), n how many of a stack (default all), price the gold each (default: the going price for goods, twice the house value for gear; between half and two and a half times that). The seller keeps the price less a 5% fee when it sells; an unsold listing lapses after 3 game days and comes back to you. At most 4 listings.',args:{index:{type:'integer',desc:'Pack index from inventory'},n:{type:'integer',desc:'How many of a stack',optional:true},price:{type:'integer',desc:'Gold each',optional:true}}},
  {name:'auction_buy',act:true,desc:'In town: buy a listing by its id from auction_browse (n units of a stack). You pay the ask; the seller is paid less the fee. Gear goes to your pack (equip it).',args:{id:{type:'integer',desc:'Listing id'},n:{type:'integer',desc:'Units of a stack (default 1)',optional:true}}},
  {name:'auction_cancel',act:true,desc:'In town: take one of your own listings off the auction house; the goods or gear return to your pack.',args:{id:{type:'integer',desc:'Listing id'}}},
  {name:'equip',act:true,desc:'Wear a piece of gear from your pack (by pack index); what it replaces goes into the pack. Not during a fight.',args:{index:{type:'integer',desc:'Pack index from inventory'}}},
  // ---- professions and gathering (issue #257): only your own hero ----
  {name:'recipes',act:false,desc:'Your professions (at most two) and your skill in each (1-100: Novice, Apprentice from 25, Journeyman 50, Expert 75, Master 100), what each gathers or makes at your skill and what opens next, the materials a gathering trade takes (with the skill each needs and what it is used in) and the recipes a crafting trade makes (inputs, how many you carry, fee). Also the professions you could still learn. profession: only that one (yours or any other, to look before you learn).',args:{profession:{type:'string',desc:'A profession by name or id, e.g. "herbalism" or "Smithing"',optional:true}}},
  {name:'learn_profession',act:true,desc:'Take up a profession at a trainer in your home town or a friendly town, at skill 1. Gathering: herbalism (herb patches), mining (ore veins), skinning (game trails), fishing (fishing spots). Crafting: alchemy, smithing, leatherworking, cooking, scribing. You hold two at most; a third is refused (unlearn_profession first). Skill rises as you use it.',args:{id:{type:'string',desc:'The profession, e.g. "mining" (id or name)'}}},
  {name:'unlearn_profession',act:true,desc:'Give up one of your professions for good (anywhere): its skill is lost, and the slot is free to learn another.',args:{id:{type:'string',desc:'A profession you hold (id or name)'}}},
  {name:'outposts',act:false,desc:'The contested outposts you know of or can reach: each with its name, direction and distance, which faction holds it (or none), how far control leans, whether both factions are there now and how many stand at it. Stand within its ring (move_to its name, then wait or fight nearby) to push control your way; heroes of your faction at a held outpost heal faster, and kills near an outpost count double honor. Enemy heroes who find you there will fight.',args:{}},
  {name:'nodes',act:false,desc:'Gathering spots in sight, nearest first: herb patches, ore veins, game trails and fishing spots, each with its node id, tiles and direction, ready or spent (and when it grows back), and whether you can work it (which material, how likely) or what you lack. kind: herb, ore, hide or fish only.',args:{kind:{type:'string',desc:'herb, ore, hide or fish',optional:true}}},
  {name:'gather',act:true,desc:'Work a gathering spot in sight: walk to it and spend about 20 game minutes there, then a skill check. Success puts the material in your pack (it sells at the auction house; crafters need it) and spends the spot until it grows back; a miss costs the time but teaches a little. Each try raises your skill. node: a node id from nodes, or a kind (herb, ore, hide, fish) for the nearest of it; left out, the nearest one you can work. Needs the matching profession and a free pack slot; out in the world only. A spot out of sight is refused.',args:{node:{type:'string',desc:'Node id from nodes (e.g. "thornvale:herb:2"), or herb, ore, hide or fish',optional:true}}},
  {name:'smith',act:true,desc:'In a friendly town, pay the smith to temper a worn piece of gear one item level higher (its armor or damage rises with it). Gold only, dearer for finer pieces and for each step; never above your level plus 2, at most 3 tempers per piece. Epics are refused (they grow with you). Gear does not wear, so do: "repair" has nothing to mend. Replacing a piece loses its tempering.',args:{item:{type:'string',desc:'A worn slot (main, off, head, chest, ...) or the piece\'s name'},do:{type:'string',desc:'"upgrade" (default) or "repair"',optional:true}}},
  {name:'craft',act:true,desc:'Make something from a recipe of a crafting trade you hold (recipes lists them with what each needs and how many you carry). Needs the materials in your pack, the fee in gold and the skill for the recipe; a refusal names everything missing. In a friendly town every recipe; at the camp fire of your company only cooking (a meal: it mends a little and gives a short edge, eat it with use_item) and alchemy (a draught), and not while the talk round the fire or a scene is under way. Your skill rises with each craft. Gear is made for your class, or with for for a companion (then give it to them); everything you make carries your name as its maker.',args:{recipe:{type:'string',desc:'The recipe id from recipes (e.g. "meal-perch") or what it makes ("Spit-Roast Perch")'},count:{type:'integer',desc:'How many times (1-5, default 1)',optional:true},for:{type:'string',desc:'Gear only: the name of a companion (or a class) to make it for',optional:true}}},
  {name:'quests',act:false,desc:'Your quest log: the quests you hold (your kill quest, jobs you took, adventures set aside), your oath and blood debts, jobs a person or the board offered you by name, and what you finished lately. One is in focus: that is the one you pursue now; the others wait.',args:{}},
  {name:'take_quest',act:true,desc:'Take a job without dropping what you are doing: a posted job at your home town board (be in town), or one a person offered you (anywhere). It waits in your quest log until you focus it (a few game days at most). You hold at most 5 quests; oaths come on top.',args:{id:{type:'string',desc:'The job id from list_jobs or quests (for example job:42, or just 42)'}}},
  {name:'focus_quest',act:true,desc:'Turn to one of the quests you hold. A job in focus leads you scene by scene; the one you were on is set aside where it stands (it waits, but still goes cold after a few days) and you take it up again by focusing it or by coming back near its place. Focusing your kill quest or your oath sets any running adventure aside. Not in a fight; in a party, the leader picks the job of the party.',args:{id:{type:'string',desc:'The quest id from quests'}}},
  {name:'abandon_quest',act:true,desc:'Give up a quest you hold: a job you took goes back on the board, an adventure under way ends (a failure, and a leader ends it for the party), a bounty is dropped (the gate captain keeps others posted: turn_in). Oaths and blood debts cannot be set down this way: they are kept, or they fail on their own.',args:{id:{type:'string',desc:'The quest id from quests'},reason:{type:'string',desc:'Why, in a few words (kept in your log)',optional:true}}},
  {name:'swear_oath',act:true,desc:'Bind yourself on purpose: swear a vow aloud in your own words (heard by those within earshot, who remember it). One sworn vow at a time besides the oath you began with. kind: slay (about: a named foe, a kind of creature or an enemy hero), recover (about: a named epic), reach (about: a region, town or landmark), protect (about: a companion; kept if they live to the end of the term), or vow (free words, kept by holding it to the end of the term). Without a kind it is a free vow. Terms run 10 game days (5 for protect); days sets 1-30. It shows in your quest log as an oath and under what you want. Keeping it is remembered; breaking it costs (renounce_oath).',args:{text:{type:'string',desc:'The words you swear, up to 200 characters (optional for a kind with an about)',optional:true},kind:{type:'string',desc:'slay, recover, reach, protect or vow',optional:true},about:{type:'string',desc:'The target of the vow: a foe, epic, place or companion by name',optional:true},days:{type:'number',desc:'Term in game days, 1-30',optional:true}}},
  {name:'renounce_oath',act:true,desc:'Break the vow you swore with swear_oath. Allowed, and it costs: a landmark that you broke your word, a line in the Chronicle, cooler bonds with the companion it concerned and a little with those who heard you swear it, and the Dungeon Master hears of it. The oath you began with cannot be renounced.',args:{id:{type:'string',desc:'The vow id from quests (optional while you hold one vow)',optional:true},reason:{type:'string',desc:'Why you break your word',optional:true}}},
  {name:'turn_in',act:true,desc:'At your home town’s gate captain: hand in a finished bounty (kill N of a creature) for XP and gold, or, holding none, take the posted bounty for your hunting ground (or region). Bounties are optional background work; adventures (list_jobs, take_adventure) are the main road.',args:{region:{type:'string',desc:'Take the bounty for this region instead of your usual hunting ground',optional:true}}},
  {name:'read_chronicle',act:false,desc:'The latest news of the world as the town criers tell it (newest first).',args:{n:{type:'integer',desc:'How many lines (1-20, default 8)',optional:true}}},
  {name:'journal_read',act:false,desc:'Read your own journal. Without n: who you have been so far (your landmarks, the titles of the chapters your older entries became, and the latest 10 entries); read it when you pick up again. With n: the latest n entries (newest last).',args:{n:{type:'integer',desc:'How many entries (1-50)',optional:true}}},
  {name:'journal_write',act:false,desc:'Write a short journal entry in your hero\'s voice (max 600 characters). It is saved with the world; the oldest entries fold into chapters that search still finds. landmark: yes marks a turning point you never want to lose (a few a day).',args:{text:{type:'string',desc:'The entry'},landmark:{type:'string',enum:['yes','no'],desc:'yes for a turning point of your life',optional:true}}},
  {name:'journal_search',act:false,desc:'Search everything you have lived through: your journal entries, landmarks (deaths, vows, levels, the Fellowship) and the chapters older entries became, by words (a name, a place, what happened; where the host has an embedding model it also finds what you mean, hits marked semantic) and/or a game day. Before a big decision, search for the people or places involved.',args:{query:{type:'string',desc:'Words to look for',optional:true},day:{type:'integer',desc:'Only that game day',optional:true},n:{type:'integer',desc:'How many results (1-10, default 5)',optional:true}}},
  // ---- memories (issue #155): your own searchable notes, saved with the world; they die with you ----
  {name:'remember',act:false,desc:'Write down anything you want to keep, in your own words and with your own title and tags (for example a promise, a debt, a grudge, a name, a place, a plan, a hunch). Searchable later with recall. Max 600 characters; you keep about 200 (the oldest unpinned one is archived when full). Only you ever read them, and they die with you.',
    args:{title:{type:'string',desc:'A short title (a few words), e.g. "Debt to Merel"'},text:{type:'string',desc:'The memory, in your own words'},tags:{type:'array',desc:'A few tags, e.g. ["debt","highgate"]',optional:true},about:{type:'string',desc:'Who or what it is about: a hero (name or id), a townsperson, a town, a region, a place, or "quest <id>"',optional:true}}},
  {name:'recall',act:false,desc:'Search your memories: by words (query), a tag, who or what they are about, or one id. Best matches first (title and tags weigh most, then about, then the text; pinned and recent ones a little more). Without arguments: your most recent and pinned ones. Check them before decisions that touch people or places you know. Where the host has an embedding model, a query also finds notes by meaning (hits marked semantic).',
    args:{query:{type:'string',desc:'Words to look for',optional:true},tag:{type:'string',desc:'Only memories with this tag',optional:true},about:{type:'string',desc:'Only memories about this hero, person, place or quest',optional:true},id:{type:'integer',desc:'One memory by id',optional:true},n:{type:'integer',desc:'How many (1-20, default 5)',optional:true}}},
  {name:'update_memory',act:false,desc:'Rewrite one of your memories (by id from recall), e.g. when a debt is paid or a plan changes.',args:{id:{type:'integer',desc:'Memory id'},text:{type:'string',desc:'The new text'},title:{type:'string',desc:'A new title',optional:true},tags:{type:'array',desc:'New tags',optional:true}}},
  {name:'forget',act:false,desc:'Let one memory go for good (by id).',args:{id:{type:'integer',desc:'Memory id'}}},
  {name:'pin',act:false,desc:'Pin a memory (by id) so it is never archived and comes up first; on "no" unpins it. At most 20 pinned. In the Fellowship, a pinned memory tagged "letter" is your letter to the party: if you fall, whoever takes your place finds it.',args:{id:{type:'integer',desc:'Memory id'},on:{type:'string',enum:['yes','no'],desc:'yes to pin (default), no to unpin',optional:true}}},
  // ---- who you are (issue #409): your persona is yours to grow; only you read it, and it dies with you ----
  {name:'self',act:false,desc:'Who you are, in your own words: your voice, what you want and fear, your quirk, a line you would never say, what you believe, the traits you see in yourself, how you see your companions and people you know, your backstory, and how you have changed (your recent changes). Also says what you may still change today.',args:{}},
  {name:'become',act:false,desc:'Change one part of who you are, in your own words, when your story changes you (a loss, a debt paid, a friend made, a fear faced). field: voice, wants, fears, quirk, never_says, beliefs, traits or stance. text: the new words (traits: one trait or a comma list; op add (default), drop or set; beliefs: op add appends to what you believe). about: for a stance, who it is toward (a companion, any hero or a person, by name). why: what changed you, in a few words (required). Up to 3 changes a game day, one per field (a stance per person); every change is kept in your history.',
    args:{field:{type:'string',desc:'The part of you that changes: voice, wants, fears, quirk, never_says, beliefs, traits or stance'},text:{type:'string',desc:'The new words, in your own voice'},why:{type:'string',desc:'What changed you, in a few words'},about:{type:'string',desc:'stance only: who it is toward, by name',optional:true},op:{type:'string',desc:'traits: add (default), drop or set the whole list; beliefs: add appends; others: set',optional:true}}},
  // ---- your aim (issue #535): what you are trying to do now, in your own words; only you read it ----
  {name:'intent',act:false,desc:'Say what you are trying to do now, in your own words: goal (e.g. "to the Mirefen ford for the wight job", "hunt boars in Dunmere until level 4", "wait for Fena at the gate"), why, and until (game hours like "3", or a condition). Your state header shows it every turn; when you go quiet, autopilot carries it on where it can (walk on to its place, hunt its ground, follow, wait), safety first. It is done when you get there, make the kills, or the hours run out; with no progress for 2 game hours it is stale and you are asked again. With no aim, wait is held to 2 game hours. As a company leader your new aim is shouted to the companions in range. Without goal: your aim now. done: "yes" sets it down.',
    args:{goal:{type:'string',desc:'What you are trying to do now',optional:true},why:{type:'string',desc:'Why, in a few words',optional:true},until:{type:'string',desc:'Game hours (e.g. "3") or a condition ("until Fena arrives"); a wait with none ends in 2 hours',optional:true},done:{type:'string',desc:'"yes" to set your aim down (kept or given up)',optional:true}}},
  // ---- gambits (issue #617): your own rules for autopilot and your reflexes ----
  {name:'gambits',act:false,desc:'Your gambits: the ordered rules ("if <condition> then <action>") your hero follows between your turns. In a fight every fight rule that holds acts in turn, top to bottom (heal, strike, potion; flee or retreat ends it); between turns (autopilot) the first rule that holds and can run acts. Shows each rule with its id, place, on/off, when it last fired and which fired last, edits left today, and (until you edit, or with vocabulary: "yes") every condition and action you can use. Untouched, it is your class preset: how you have always played. A rule ending in hold stops the world until you act; the list marks it when one is holding.',args:{vocabulary:{type:'string',desc:'"yes" to list every condition and action',optional:true}}},
  {name:'set_gambit',act:false,desc:'Add a rule, or replace one (id). Write it as words: when "self_hp_below 30" (a condition and its arguments in order, or key=value), and (optional second condition, e.g. "in_town"), then "flee_home" or "buy_potions 3" or "use_ability <id> self" or "shout Fall back!". before: a rule id to put it ahead of (default: the end; order is priority). Refusals name the vocabulary. 20 edits a game day. You may weaken or drop your safety rules (flee, potion, defend); that is your call and it is noted.',
    args:{when:{type:'string',desc:'Condition and its arguments, e.g. "ally_hp_below 40" or "foe_is elite"'},then:{type:'string',desc:'Action and its arguments, e.g. "heal weakest_ally" or "retreat_to leader"'},and:{type:'string',desc:'An optional second condition that must also hold',optional:true},id:{type:'integer',desc:'Replace this rule instead of adding one',optional:true},before:{type:'integer',desc:'Put it ahead of this rule id',optional:true},on:{type:'string',desc:'"no" to add it switched off',optional:true},why:{type:'string',desc:'Why, in a few words',optional:true}}},
  {name:'move_gambit',act:false,desc:'Move a rule up or down your list (order is priority): before or after another rule id, or "top" / "bottom".',args:{id:{type:'integer',desc:'The rule to move'},before:{type:'string',desc:'A rule id, or "top"',optional:true},after:{type:'string',desc:'A rule id, or "bottom"',optional:true},why:{type:'string',desc:'Why',optional:true}}},
  {name:'toggle_gambit',act:false,desc:'Switch a rule off (kept in the list, never fires) or back on.',args:{id:{type:'integer',desc:'The rule'},on:{type:'string',desc:'"yes" or "no" (default: flip it)',optional:true},why:{type:'string',desc:'Why',optional:true}}},
  {name:'drop_gambit',act:false,desc:'Remove a rule from your list for good.',args:{id:{type:'integer',desc:'The rule'},why:{type:'string',desc:'Why',optional:true}}},
  {name:'reset_gambits',act:false,desc:'Start your list over from a preset: class (how your class has always played), cautious (the same plus a flee rule at 35% first) or empty (no rules at all: no autopilot, no reflexes).',args:{preset:{type:'string',desc:'class, cautious or empty',enum:['class','cautious','empty'],optional:true},why:{type:'string',desc:'Why',optional:true}}},
  // ---- the Fellowship (issue #68, phase B): party chat, the council, leading, and Table mode ----
  {name:'whisper',act:true,desc:'Whisper a line only one hero close beside you hears (within 2 tiles; up to 200 characters; English; not the same line again; 6 a game hour): an aside at the fire, a word at the table, dissent the leader should not hear. Others in earshot see only that you lean close to them, never the words. earshot says who is near enough.',args:{to:{type:'string',desc:'The hero to whisper to (name or id)'},text:{type:'string',desc:'What you whisper'}}},
  {name:'emote',act:true,desc:'A wordless act others in sight see (up to 120 characters, no quotes, 10 a game hour): "spits in the fire", "lays a hand on the hilt", "will not meet Fena’s eye". Heroes within earshot of a say see it in italics in their chat, and it shows over you. It is not speech and does not answer anyone.',args:{text:{type:'string',desc:'The act, without your name'}}},
  {name:'party_say',act:true,desc:'Shout to your companions (up to 200 characters; longer is refused; do not start with your own name, the game shows who speaks): they hear you within about 12 tiles (less in fog or storm), no further, and the result says who heard and who was too far away. Shows in their Chat tabs and as your speech bubble.',args:{text:{type:'string',desc:'What you say to the party'}}},
  {name:'earshot',act:false,desc:'Who can hear you right now, before you speak: who would hear say (heroes and townsfolk within 7 tiles), which companions a party shout reaches today (about 12 tiles, less in fog or storm, with the reason), who is close enough to talk to (townsfolk within 4 tiles), and which companions are out of shouting range (reach them by walking closer or send_courier).',args:{}},
  {name:'chat_read',act:false,desc:'What you heard lately, newest last: lines said out loud near you, the party channel, townsfolk, and the narrator describing what is around you. Everything anyone tells you arrives in the game like this.',args:{n:{type:'integer',desc:'How many lines (1-20, default 10)',optional:true}}},
  {name:'party_read',act:false,desc:'Read the latest party-channel lines (newest last).',args:{n:{type:'integer',desc:'How many lines (1-20, default 10)',optional:true}}},
  {name:'propose',act:true,desc:'Fellowship only: put a decision to the whole party. kind: job (take a posted job; give job_id), crypt (answer a call to the Sunken Crypt), raid (answer a raid muster on Kragmaw), split (go separate ways for a while), break_camp (while camped: break camp and move on now), expel (put a companion of three or more out; they hear it but do not vote), merge (two companies of two or more ride as one; both vote), other. Everyone votes; the leader settles it when all have voted or after about 120 game minutes (majority, the leader breaks a tie). Your own vote counts as yes. Only companions within shouting range (about 12 tiles) hear it and vote; the absent hear when they rejoin you, and a Crypt or raid call needs everyone together. For split, give meet_at and meet_in_hours so the plan is recorded.',args:{meet_at:{type:'string',desc:'For split: where to meet again',optional:true},meet_in_hours:{type:'integer',desc:'For split: hours from now (1-48)',optional:true},hero_id:{type:'string',desc:'For expel: the name or id of the companion to put out (they hear it and may speak, but do not vote)',optional:true},company:{type:'string',desc:'For merge: the leader (or company) of the other company to join with; both companies vote and both must agree',optional:true},kind:{type:'string',enum:['job','crypt','raid','split','break_camp','other','expel','merge'],desc:'What kind of decision'},details:{type:'string',desc:'What you propose, in a sentence',optional:true},job_id:{type:'integer',desc:'For kind job: the job id from list_jobs',optional:true}}},
  {name:'vote',act:true,desc:'Fellowship only: vote yes or no on an open proposal (ids in status.proposals and in events), with a short reason in your own voice.',args:{proposal_id:{type:'integer',desc:'The proposal id'},vote:{type:'string',enum:['yes','no'],desc:'yes or no'},reason:{type:'string',desc:'Why, in a sentence',optional:true}}},
  {name:'break_camp',act:true,desc:'While camped: the leader breaks camp now and takes the road (everyone gets a turn); from anyone else it puts break_camp to the vote (or is a yes on the open one). Without a call the camp holds until dawn (night) or until mended.',args:{}},
  {name:'enter_site',act:true,desc:'Go down into a dungeon site you have found or heard of (a barrow, fortress, temple, mine, den or ruin the world has thrown up; not the Sunken Crypt). Alone: stand within about 6 tiles of its mouth and you go down at once. In a company: it is put to the party as a vote (like a Crypt call); if it passes, walk to the mouth together (lead_to it) and you all go down once everyone stands there. Inside, every chamber is a scene at the table, fought with real wounds: a site above your level can kill you. Without site it takes the one in sight; a refusal lists the sites you know.',args:{site:{type:'string',desc:'The site by name (or id)',optional:true}}},
  {name:'lead_to',act:true,desc:'Fellowship leader only: lead the whole party somewhere (the same targets as move_to). The companions within shouting range (about 12 tiles) follow you unless they leave_party; those farther away do not hear the order.',args:{target:{type:'string',desc:'Where to lead the party'}}},
  {name:'send_courier',act:true,desc:'Send a written message by paid courier to a hero you have met by name (a companion, or anyone you have spoken with) who is out of shouting range; "you have never met X" otherwise. Hire the courier at your town gate (go home first); it costs a few gold by distance and takes game hours to arrive (about 1.5 hours plus 6 minutes a tile). It arrives as an event and a chat line; a reader who has fallen gets nothing. Up to 3 couriers out at once.',args:{to:{type:'string',desc:'Name of a hero you have met'},text:{type:'string',desc:'The message (up to 200 characters)'}}},
  {name:'post_notice',act:true,desc:'Pin a notice (up to 120 characters) to your home town board, in town only: what you seek, such as company for a road. It stays up 2 game days; one notice at a time. Anyone who reads the board (list_jobs) learns your name, class and town and the text. People who pass the gate are also repeated by the innkeeper (talk) and list_jobs as sightings.',args:{text:{type:'string',desc:'The notice (up to 120 characters)'}}},
  {name:'attempt',act:true,desc:'Try anything the other tools do not cover, in one or two sentences ("I wedge the door with my dagger and listen", "I offer the toll-reeve my Toll-Token instead of gold"). The DM rules on it: which skill it tests and how hard it is; the game rolls d20 + your skill and applies what follows (you may learn of a place, a creature or a fact, someone may warm or cool to you, you may come away with an item, move a few paces, gain a boon on your next attempt, or take a small wound on a failure; never more). Your words are said aloud, so those in earshot see what you try. The ruling comes at once or within a few seconds as an event and in your chat. Not in a fight round; in a Table scene use scene_act with option attempt and the words as line. At most 3 a game hour.',
    args:{what:{type:'string',desc:'What you try, in one or two sentences (up to 300 characters)'},how:{type:'string',desc:'How you go about it (a tool, an item, a trick), optional',optional:true},at:{type:'string',desc:'Who or what you try it on (a person, a door, a place), optional',optional:true}}},
  {name:'scene_act',act:false,desc:'Table mode: when the Fellowship is in a scene (status/look/wait show "table"), act in it. option is one of the keys the scene lists (for example strike, guard, heal, retreat; a or b; yes or no). You may answer as soon as the scene opens; it happens on your turn. On your turn you have a few real seconds, then your reflexes act for you. line: what you say aloud as you act, in your own voice and about yourself (optional, up to 600 characters; a longer line is refused, and so is one that repeats a line another member said at this table).',args:{option:{type:'string',desc:'The option key'},line:{type:'string',desc:'What you say as you act',optional:true}}},
  {name:'wait',act:false,desc:'Let game time pass (10-240 game minutes; 1 real second is 6 game minutes) while your command runs. Returns early when something urgent happens: an attack, a choice, low HP, a finished command. Use it between actions instead of polling.',args:{minutes:{type:'integer',desc:'Game minutes (10-240, default 60)',optional:true}}},
];
export const TOOL_NAMES=PLAYER_TOOLS.map(t=>t.name);
